func NotifyTypeToString(notifyType uint16) string {
	if name, ok := notifyNames[notifyType]; ok {
		return name
	}
	if notifyType < 16384 {
		return fmt.Sprintf("UNKNOWN_ERROR(%d)", notifyType)
	}
	return fmt.Sprintf("UNKNOWN_STATUS(%d)", notifyType)
}

func EncrToString(id uint16) string {
	return algorithmName(AlgorithmType(id), map[AlgorithmType]string{
		ENCR_DES_IV64: "DES_IV64", ENCR_DES: "DES", ENCR_3DES: "3DES", ENCR_RC5: "RC5",
		ENCR_IDEA: "IDEA", ENCR_CAST: "CAST", ENCR_BLOWFISH: "BLOWFISH", ENCR_3IDEA: "3IDEA",
		ENCR_DES_IV32: "DES_IV32", ENCR_NULL: "NULL", ENCR_AES_CBC: "AES_CBC",
		ENCR_AES_CTR: "AES_CTR", ENCR_AES_CCM_8: "AES_CCM_8", ENCR_AES_CCM_12: "AES_CCM_12",
		ENCR_AES_CCM_16: "AES_CCM_16", ENCR_AES_GCM_8: "AES_GCM_8",
		ENCR_AES_GCM_12: "AES_GCM_12", ENCR_AES_GCM_16: "AES_GCM_16",
	})
}

