func DHToString(id uint16) string {
	if id == 0 {
		return "NONE"
	}
	return algorithmName(AlgorithmType(id), map[AlgorithmType]string{
		MODP_768_bit: "MODP_768", MODP_1024_bit: "MODP_1024", MODP_1536_bit: "MODP_1536",
		MODP_2048_bit: "MODP_2048", MODP_3072_bit: "MODP_3072", MODP_4096_bit: "MODP_4096",
		MODP_6144_bit: "MODP_6144", MODP_8192_bit: "MODP_8192",
		ECP_256_bit: "ECP_256", ECP_384_bit: "ECP_384",
	})
}

func algorithmName(id AlgorithmType, names map[AlgorithmType]string) string {
	if name, ok := names[id]; ok {
		return name
	}
	return "UNKNOWN"
}
